pub enum AssertOperand {
    /// A qualified name like `R1.value`.
    QualifiedName {
        parts: Vec<String>,
        span: Span,
    },
    /// A physical value like `10kohm`.
    Physical(PhysicalValue),
    /// A dimension value like `0.3mm`.
    Dimension(Dimension),
    /// A bare number.
    Number {
        value: f64,
        span: Span,
    },
}

