// v2-modules.cypcb — Module definitions with nested components, pin declarations, and instantiation
//
// Demonstrates the v2 module system: encapsulating components, nets, and
// exposing pins for hierarchical design.

version 1

// A reusable voltage regulator module
module PowerSupply {
    component U1 ic "SOT-23" {
        value "LDO-3V3"
        at 0mm, 0mm
    }

    component C_IN capacitor "0402" {
        value 100nF
        at -3mm, 0mm
    }

    component C_OUT capacitor "0402" {
        value 10uF
        at 3mm, 0mm
    }

    // Internal nets
    net input_rail {
        U1.1
        C_IN.1
    }

    net output_rail {
        U1.3
        C_OUT.1
    }

    net gnd_internal {
        U1.2
        C_IN.2
        C_OUT.2
    }

    // Exposed pins — the module's external interface
    pin VIN
    pin VOUT
    pin GND
}

// A simple LED driver module
module LedDriver {
    component D1 led "0603" {
        value "RED"
        at 0mm, 0mm
    }

    component R1 resistor "0402" {
        value 330ohm
        at 0mm, 3mm
    }

    net led_anode {
        R1.2
        D1.1
    }

    pin INPUT
    pin GND
}

// Top-level board using the modules
board main_board {
    size 50mm x 30mm
    layers 2
}

// v2-interfaces.cypcb — Interface definitions for typed pin groups
//
// Demonstrates declaring standard interfaces (I2C, SPI, Power) that can
// be used to ensure modules expose the correct pins.

version 1

// Standard I2C interface — 2-wire bidirectional bus
interface I2C {
    pin SDA
    pin SCL
}

// Standard SPI interface — 4-wire master/slave bus
interface SPI {
    pin MOSI
    pin MISO
    pin SCK
    pin CS
}

// Power interface — supply and ground
interface Power {
    pin VCC
    pin GND
}

// UART interface — asynchronous serial
interface UART {
    pin TX
    pin RX
}

// A sensor module exposing I2C and Power interfaces
module TemperatureSensor {
    component U1 ic "SOIC-8" {
        value "TMP102"
        at 0mm, 0mm
    }

    component C1 capacitor "0402" {
        value 100nF
        at 3mm, 0mm
    }

    net vdd {
        U1.1
        C1.1
    }

    net gnd_int {
        U1.4
        C1.2
    }

    // I2C pins
    pin SDA
    pin SCL
    // Power pins
    pin VCC
    pin GND
}

// A display module exposing SPI and Power interfaces
module OledDisplay {
    component U1 ic "SOIC-8" {
        value "SSD1306"
        at 0mm, 0mm
    }

    component C1 capacitor "0402" {
        value 10uF
        at 4mm, 0mm
    }

    component C2 capacitor "0402" {
        value 100nF
        at 4mm, 3mm
    }

    net vdd {
        U1.1
        C1.1
        C2.1
    }

    // SPI pins
    pin MOSI
    pin MISO
    pin SCK
    pin CS
    // Power pins
    pin VCC
    pin GND
}

// v2-constraints.cypcb — Assert statements with comparisons, tolerances, and physical units
//
// Demonstrates constraint assertions: comparisons (>=, <=, ==),
// tolerance syntax (+/- percentage, +/- absolute, range), and
// physical unit values on components.

version 1

board constraint_test {
    size 60mm x 40mm
    layers 4
}

// Components with typed physical unit values
component R1 resistor "0402" {
    value 10kohm
    at 10mm, 10mm
}

component R2 resistor "0603" {
    value 4.7kohm
    at 20mm, 10mm
}

component C1 capacitor "0402" {
    value 100nF
    at 10mm, 20mm
}

component C2 capacitor "0805" {
    value 10uF
    at 20mm, 20mm
}

component U1 ic "SOIC-8" {
    value "LDO-3V3"
    at 30mm, 15mm
}

component L1 inductor "0805" {
    value 10uH
    at 40mm, 15mm
}

// Comparison assertions
assert R1.value >= 10kohm
assert board.layers == 4

// Tolerance assertions — percentage tolerance
assert R1.value within 10kohm +/- 5%

// Tolerance assertions — absolute tolerance
assert U1.output within 3.3V +/- 0.1V

// Tolerance assertions — range tolerance
assert C1.value within 100nF to 220nF

// Nets connecting the components
net VCC {
    U1.1
    R1.1
    C2.1
}

net GND {
    U1.4
    R1.2
    R2.2
    C1.2
    C2.2
    L1.2
}

net signal_a {
    R2.1
    C1.1
    U1.3
}

